        current_url = str(getattr(page, "url", "") or getattr(latest, "url", "") or "")
        return _response_v1112(
            current_url,
            int(getattr(latest, "status_code", 200) or 200),
            "",
            dict(getattr(latest, "headers", {}) or {}),
