            if not retry_challenge or attempt + 1 >= attempts:
                raise _GyingBrowserChallengeCompatFailureV1112(
                    "观影 CloakBrowser 验证后原请求仍返回挑战页"
                )

            solved_kind = kind
            self._gying_browser_solve_v1112(
                row,
                node,
                response,
                kind,
                timeout,
            )
            self._gying_browser_sync_shadow_v1112(row, session, node)

        raise _GyingBrowserChallengeCompatFailureV1112("观影 CloakBrowser 请求重试次数已耗尽")

    def _gying_request(
        self,
        session: requests.Session,
        node: str,
        method: str,
        url: str,
        *,
        retry_challenge: bool = True,
        **kwargs: Any,
    ) -> requests.Response:
        canonical = canonical_gying_node(node) or str(node or "").rstrip("/")
        if not canonical or not _same_origin_v1112(canonical + "/", str(url or "")):
            return super()._gying_request(
                session,
                node,
                method,
                url,
                retry_challenge=retry_challenge,
                **kwargs,
            )

        timeout = int(
            kwargs.pop(
                "timeout",
                int(getattr(self, "_provider_timeout", 15) or 15),
            )
            or 15
        )
        kwargs.pop("allow_redirects", None)
        row = self._gying_browser_row_v1112(canonical)
        try:
            return self._gying_browser_submit_v1112(
                row,
                self._gying_browser_request_in_thread_v1112,
                row,
                session,
                canonical,
                str(method or "GET").upper(),
                str(url or ""),
                timeout,
                bool(retry_challenge),
                dict(kwargs),
            )
        except _GyingBrowserUnavailableV1112 as err:
            if not bool(getattr(self, "_gying_browser_fallback_logged_v1112", False)):
                self._gying_browser_fallback_logged_v1112 = True
                self._gying_auth_log(
                    "WARNING",
                    "CloakBrowser 当前不可用，GYING 暂时回退 PanSou requests 链：%s",
                    str(err)[:160],
                )
            return super()._gying_request(
                session,
                canonical,
                method,
                url,
                retry_challenge=retry_challenge,
                timeout=timeout,
                **kwargs,
            )
        except (_GyingBrowserChallengeCompatFailureV1112, RuntimeError) as err:
            # Browser 可用但 challenge/PoW 兼容失败 → 同节点进入历史 PanSou PoW，禁止直接换节点
            if not _is_browser_challenge_compat_failure_v1112(err):
                raise
            self._gying_auth_log(
                "WARNING",
                "【观影】【Browser】challenge compatibility failed fallback=pansou node=%s err=%s",
                canonical,
                str(err)[:160],
            )
            # 避免 Browser 临时 challenge Cookie 污染 PanSou Session
            try:
                from .gying_fallback_reuse_v1113 import _drop_stale_challenge_cookies_v1113

                _drop_stale_challenge_cookies_v1113(session)
            except Exception:
                pass
            return super()._gying_request(
                session,
                canonical,
                method,
                url,
                retry_challenge=retry_challenge,
                timeout=timeout,
                **kwargs,
            )

    def api_viewing_auth_start(self, force: bool = False) -> Dict[str, Any]:
        if force:
            self._gying_browser_close_all_v1112()
        return dict(super().api_viewing_auth_start(force=bool(force)) or {})


